package com.example.Hospital.Management.System.controllers; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.services.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/medicalRecord") public class MedicalRecordController{private final MedicalRecordService s;public MedicalRecordController(MedicalRecordService s){this.s=s;}@PostMapping public ResponseEntity<MedicalRecordDTO> create(@Valid @RequestBody MedicalRecordDTO d){return ResponseEntity.status(201).body(s.create(d));}@GetMapping public List<MedicalRecordDTO> all(){return s.all();}@GetMapping("/{id}") public MedicalRecordDTO get(@PathVariable Long id){return s.get(id);}@PutMapping("/{id}") public MedicalRecordDTO update(@PathVariable Long id,@Valid @RequestBody MedicalRecordDTO d){return s.update(id,d);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}@GetMapping("/patient/{id}") public List<MedicalRecordDTO> patient(@PathVariable Long id){return s.patient(id);}}
